arr_e3_sun		equ ntc_bss + 222		; 6 bytes
arr_e3_op		equ ntc_bss + 228		; 6 bytes
arr_e3_oc		equ ntc_bss + 234		; 6 bytes
arr_e3_obj		equ ntc_bss + 240		; 512 bytes
arr_e3_ppos		equ ntc_bss + 752		; 6 bytes
arr_e3_aimp		equ ntc_bss + 758		; 6 bytes
arr_e3_aimv		equ ntc_bss + 764		; 6 bytes
arr_e3_pup		equ ntc_bss + 770		; 6 bytes
arr_e3_vwx		equ ntc_bss + 776		; 64 bytes
arr_e3_vwy		equ ntc_bss + 840		; 64 bytes
arr_e3_vwz		equ ntc_bss + 904		; 64 bytes
arr_e3_wq		equ ntc_bss + 968		; 24 bytes
arr_e3_suc		equ ntc_bss + 992		; 6 bytes
arr_e3_od		equ ntc_bss + 998		; 6 bytes
arr_e3_ccl		equ ntc_bss + 1004		; 18 bytes
arr_e3_oe		equ ntc_bss + 1022		; 6 bytes
arr_e3_osn		equ ntc_bss + 1028		; 6 bytes
arr_e3_ov		equ ntc_bss + 1034		; 72 bytes
arr_e3_osx		equ ntc_bss + 1106		; 24 bytes
arr_e3_osy		equ ntc_bss + 1130		; 24 bytes
arr_e3_cla		equ ntc_bss + 1154		; 60 bytes
arr_e3_clb		equ ntc_bss + 1214		; 60 bytes
arr_obj3d_ocls		equ ntc_bss + 1274		; 64 bytes
arr_obj3d_omask		equ ntc_bss + 1338		; 64 bytes
arr_obj3d_omv		equ ntc_bss + 1402		; 64 bytes
arr_obj3d_oflg		equ ntc_bss + 1466		; 64 bytes
arr_obj3d_ost		equ ntc_bss + 1530		; 64 bytes
arr_obj3d_otm		equ ntc_bss + 1594		; 64 bytes
arr_obj3d_olife		equ ntc_bss + 1658		; 64 bytes
arr_obj3d_ogun		equ ntc_bss + 1722		; 64 bytes
arr_obj3d_otype		equ ntc_bss + 1786		; 64 bytes
arr_obj3d_ouv		equ ntc_bss + 1850		; 64 bytes
arr_obj3d_ovx		equ ntc_bss + 1914		; 64 bytes
arr_obj3d_ovy		equ ntc_bss + 1978		; 64 bytes
arr_obj3d_ovz		equ ntc_bss + 2042		; 64 bytes
arr_obj3d_opa		equ ntc_bss + 2106		; 64 bytes
arr_obj3d_opb		equ ntc_bss + 2170		; 64 bytes
arr_obj3d_ospd		equ ntc_bss + 2234		; 64 bytes
arr_obj3d_odist		equ ntc_bss + 2298		; 64 bytes
arr_obj3d_ohw		equ ntc_bss + 2362		; 64 bytes
arr_obj3d_ohh		equ ntc_bss + 2426		; 64 bytes
arr_obj3d_olz		equ ntc_bss + 2490		; 64 bytes
arr_obj3d_evq		equ ntc_bss + 2554		; 64 bytes
arr_obj3d_evb		equ ntc_bss + 2618		; 64 bytes
ntc_bss_size	equ 2682
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables

; ============================================================
; ZX Spectrum Next: the start stub (bank 5, page 11 at #7E00) and the NEX file
; ============================================================
			ASSERT ntc_free <= #BE00, "the program and its arrays must end below #BE00 (the stack is #BE00-#BFFF, the screen #C000-#FFFF)"

; Option NexData: "ROCKS.DAT", 1 blocks of 16K, in their banks
			MMU 0 1, 2
			org #0000
			INCBIN "ROCKS.DAT", 0, 16384
			MMU 3, 11			; page 11 (bank 5's second half) at #6000 to assemble the stub
			org #7E00
zxn_boot:
			di
			ld bc, #243B		; NextReg select (#253B: its value)
			ld a, 6			; Peripheral 2: the NMI buttons off (bit 3 Multiface M1, bit 4 DivMMC DRIVE)
			out (c), a
			inc b
			in a, (c)
			and %11100111
			out (c), a
			dec b
; DivMMC: its automatic paging stays as NextZXOS left it (on) - turning it off and on
; again loses esxDOS's state in some emulators - but its entry points are cut to RST 8
; with ROM 3 selected (#B8 = 2, #B9 = 0: the RST vectors need ROM 3; #BB = 0: no #3Dxx,
; #0066, tape traps). A program never does rst 8 with ROM 3 in, so nothing pages it in;
; CyborgOS's SD drive does exactly that for its esxDOS calls (ROM 3 in slots 0-1, rst 8).
; Tested on NextZXOS 2.06H (JNEXT, 2026-10-21): esxDOS calls work with these - when the NEX
; is started by NextZXOS (the browser, .nexload, an autoexec), not loaded as a snapshot,
; which skips the DOS's own set-up and leaves every call answering "nonsense" (2)
			ld a, #B8
			out (c), a
			inc b
			ld a, 2
			out (c), a
			dec b
			ld a, #B9
			out (c), a
			inc b
			xor a
			out (c), a
			dec b
			ld a, #BB
			out (c), a
			inc b
			xor a
			out (c), a
			dec b
; (no out (#E3): DivMMC's memory is already out when a NEX starts - .nexload leaves it so -
; and writing the port selects its RAM bank 0 and drops MAPRAM, which loses NextZXOS's esxDOS
; state: its file handles are in DivMMC RAM. With it untouched, RST 8 calls work from the program
; (automap on, the ROM in slots 0-1 for the call: CyborgOS's SD drive does that)
			ld a, 7			; CPU speed: 28MHz
			out (c), a
			inc b
			ld a, 3
			out (c), a
			dec b
			ld hl, zxn_mmu		; the slots but 3
			ld e, 7
zxn_bmmu:
			ld a, (hl)
			inc hl
			out (c), a
			inc b
			ld a, (hl)
			inc hl
			out (c), a
			dec b
			dec e
			jr nz, zxn_bmmu
			jp zxn_boot2 + #8000	; on in the copy at #E000-#FFFF (page 11 in slot 7)
zxn_boot2:
			ld a, #53			; slot 3: page 19
			out (c), a
			inc b
			ld a, 19
			out (c), a
			ld hl, #C9FB		; #0038: ei, ret until ntc_plat_irqon puts its jump there
			ld (#0038), hl
			im 1
			jp ntc_start
zxn_mmu:	db #50, 16, #51, 17, #52, 18, #54, 20, #55, 21, #56, 10, #57, 11
			SAVENEX OPEN "ROCKS.NEX", zxn_boot, #7E00
			SAVENEX CORE 3, 0, 0
			SAVENEX CFG 0
			SAVENEX BANK 5, 1, 8, 9, 10
			SAVENEX CLOSE